import {COVER_LAYOUTS} from './cover-layouts.js';
import {paintCaption} from './caption-render.js';
export const CAPTION_DEFAULTS={font:'Golos Text',size:4.2,position:'bottom',style:'plate',safe:10};
export function captionStyle(value={}){return {color:/^#[a-f0-9]{6}$/i.test(value.color||'')?value.color:'#ffffff',highlight:/^#[a-f0-9]{6}$/i.test(value.highlight||'')?value.highlight:'#f4d740',font:['Golos Text','Roboto Condensed'].includes(value.font)?value.font:'Golos Text',size:Math.min(7,Math.max(2.5,Number(value.size)||4.2)),position:['bottom','center','top'].includes(value.position)?value.position:'bottom',style:['plate','outline','plain','karaoke'].includes(value.style)?value.style:'plate',safe:Math.min(25,Math.max(5,Number(value.safe)||10))}}
export function validateCues(cues,duration=Infinity){if(!Array.isArray(cues)||cues.length>1000)throw Error('Максимум 1000 реплик.');const sorted=cues.map((c,i)=>{const start=Number(c.start),end=Number(c.end),text=String(c.text||'').trim();if(!text||text.length>500||!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>duration+.001)throw Error('Реплика '+(i+1)+': проверьте текст и время в пределах ролика.');let words;if(c.words){if(!Array.isArray(c.words)||c.words.length>100)throw Error('Проверьте слова субтитра');words=c.words.map(w=>({start:Number(w.start),end:Number(w.end),text:String(w.text||w.word||'').slice(0,100)}));for(let j=0;j<words.length;j++){const w=words[j];if(!w.text||!Number.isFinite(w.start)||!Number.isFinite(w.end)||w.start<start-.001||w.end>end+.001||w.end<=w.start||j&&w.start<words[j-1].end-.001)throw Error('Проверьте таймкоды слов')}}return {start,end,text,...(words?{words}:{})}}).sort((a,b)=>a.start-b.start);for(let i=1;i<sorted.length;i++)if(sorted[i].start<sorted[i-1].end-.001)throw Error('Реплики '+i+' и '+(i+1)+' пересекаются. Измените время.');return sorted}
export const COVER_STYLES={automotive:'Обзор · крупный заголовок',informative:'Информативная',clickbait:'Кликбейтная',minimal:'Минималистичная',editorial:'Журнальная'};
export function coverSettings(value={}){return {theme:['auto','automotive','coffee','technology','travel','editorial'].includes(value.theme)?value.theme:'auto',gradient:value.gradient!==false,gradientEnd:/^#[a-f0-9]{6}$/i.test(value.gradientEnd||'')?value.gradientEnd:'#162331',designVersion:value.designVersion===2?2:0,layout:Object.hasOwn(COVER_LAYOUTS,value.layout)?value.layout:value.style==='clickbait'?'split':value.style==='editorial'?'editorial':'poster',align:value.align==='center'?'center':'left',font:['Golos Text','Roboto Condensed'].includes(value.font)?value.font:'Golos Text',textSize:Math.min(14,Math.max(5,Number(value.textSize)||9)),position:['top','center','bottom'].includes(value.position)?value.position:'top',accent:/^#[a-f0-9]{6}$/i.test(value.accent||'')?value.accent:'#f4d740',style:Object.hasOwn(COVER_STYLES,value.style)?value.style:'informative',title:String(value.title||'').slice(0,100),subtitle:String(value.subtitle||'').slice(0,150),frame:Math.max(0,Number(value.frame)||0),backgroundMode:['frame','upload'].includes(value.backgroundMode)?value.backgroundMode:'frame',backgroundImage:typeof value.backgroundImage==='string'&&value.backgroundImage.length<=4000000&&/^data:image\/(png|jpeg|webp);base64,/.test(value.backgroundImage)?value.backgroundImage:'',backgroundName:String(value.backgroundName||'').slice(0,120),logo:value.logo!==false,shade:Math.min(.75,Math.max(0,Number.isFinite(Number(value.shade))?Number(value.shade):.22))}}
export function wrapText(ctx,text,maxWidth){const lines=[];let line='';for(const word of String(text).split(/\s+/)){const candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width>maxWidth&&line){lines.push(line);line=word}else line=candidate}if(line)lines.push(line);return lines}
export function drawCaption(ctx,canvas,text,value,time=0,cue={}){paintCaption(ctx,canvas,text,captionStyle(value),time,cue)}
